+package sql
+
+import (
+	"context"
+	"log"
+	"multiChat/internal/ifs"
+
+	"github.com/jackc/pgx/v5/pgxpool"
+)
+
+type DbRepo struct {
+	conn *pgxpool.Pool
+}
+
+func (S DbRepo) UserInsert(ctx context.Context, user ifs.Users) error {
+	query := `insert into users (id) values ($1);`
+	_, err := S.conn.Exec(ctx, query, user.Id)
+	return err
+}
+
+func (S DbRepo) UserSelectIdLike(ctx context.Context, id int) (ifs.Users, error) {
+	query := `select id,created_at,updated_at from users where id = $1;`
+	users, err := S.conn.Query(ctx, query, id)
+
+	defer users.Close()
+
+	if err != nil {
+		return ifs.Users{}, err
+	}
+
+	var u ifs.Users
+
+	for users.Next() {
+		err := users.Scan(
+			&u.Id,
+			&u.CreatedAt,
+			&u.UpdatedAt)
+		if err != nil {
+			log.Fatal("Unable to scan:", err)
+		}
+	}
+	return u, nil
+}
+
+func (S DbRepo) UserDelete(ctx context.Context, str int) error {
+	query := "delete from users where id =$1;"
+	_, err := S.conn.Exec(ctx, query, str)
+	if err == nil {
+		log.Printf("Из базы удалён пользователь: %v", str)
+	}
+	return err
+}
+
+func NewDbRepo(conn *pgxpool.Pool) *DbRepo {
+	return &DbRepo{conn: conn}
+}
+
+func (S DbRepo) MessagesInsert(ctx context.Context, messages ifs.Messages) error {
+	query := `insert into messages (user_id,messenger_type,messenger_message_id,message_text,reply_to_message_id) values ($1,$2,$3,$4,$5);`
+	str, err := S.conn.Exec(ctx, query, messages.UserId, messages.MessengerType, messages.MessengerUserId, messages.MessageText, messages.ReplyToMessageId)
+	if err == nil {
+		log.Printf("В базу добавлен пользователь: %v", str)
+	}
+	return err
+}

