+package sql
+
+import (
+	"context"
+	"multiChat/internal/cfg"
+	"multiChat/internal/ifs"
+	"reflect"
+	"testing"
+
+	"github.com/jackc/pgx/v5/pgxpool"
+)
+
+func TestDbRepo_UserSelectIdLike(t *testing.T) {
+	ctx := context.Background()
+	connDB := cfg.NewConnDB(ctx)
+
+	type fields struct {
+		conn *pgxpool.Pool
+	}
+	type args struct {
+		ctx context.Context
+		id  int
+	}
+	tests := []struct {
+		name    string
+		fields  fields
+		args    args
+		want    ifs.Users
+		wantErr bool
+	}{
+		{
+			name: "UserSelectIdLike Успешный тест",
+			args: args{
+				ctx: ctx,
+				id:  1,
+			},
+			fields: fields{
+				conn: connDB.Conn,
+			},
+			want:    ifs.Users{Id: 1},
+			wantErr: false,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			S := DbRepo{
+				conn: tt.fields.conn,
+			}
+			got, err := S.UserSelectIdLike(tt.args.ctx, tt.args.id)
+			if (err != nil) != tt.wantErr {
+				t.Errorf("UserSelectIdLike() error = %v, wantErr %v", err, tt.wantErr)
+				return
+			}
+			if !reflect.DeepEqual(got.Id, tt.want.Id) {
+				t.Errorf("UserSelectIdLike() got = %v, want %v", got, tt.want)
+			}
+		})
+	}
+}
+
+func TestDbRepo_UserInsert(t *testing.T) {
+	ctx := context.Background()
+	connDB := cfg.NewConnDB(ctx)
+
+	type fields struct {
+		conn *pgxpool.Pool
+	}
+	type args struct {
+		ctx  context.Context
+		user ifs.Users
+	}
+	tests := []struct {
+		name    string
+		fields  fields
+		args    args
+		wantErr bool
+	}{
+		{
+			name: "TestDbRepo_UserInsert Успешный тест",
+			args: args{
+				ctx:  ctx,
+				user: ifs.Users{Id: 10},
+			},
+			fields: fields{
+				conn: connDB.Conn,
+			},
+			wantErr: false,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			S := DbRepo{
+				conn: tt.fields.conn,
+			}
+			if err := S.UserInsert(tt.args.ctx, tt.args.user); (err != nil) != tt.wantErr {
+				t.Errorf("UserInsert() error = %v, wantErr %v", err, tt.wantErr)
+			}
+			user, err := S.UserSelectIdLike(tt.args.ctx, tt.args.user.Id)
+			if (err != nil) && (user.Id != tt.args.user.Id) {
+				t.Errorf("UserInsert() error = %v, wantErr %v", err, tt.wantErr)
+			}
+			err = S.UserDelete(tt.args.ctx, tt.args.user.Id)
+			if err != nil {
+				t.Errorf("UserInsert() error = %v, wantErr %v", err, tt.wantErr)
+			}
+		})
+	}
+}

